c.python:
class Solution:
    def losingPlayer(self, x: int, y: int) -> str:
        alice = True
        while x >= 1 and y >= 4:
            x -= 1; y -= 4; alice = not alice
        return "Bob" if alice else "Alice"

c.cpp:
class Solution {
public:
    string losingPlayer(int x, int y) {
        bool alice = true;
        while (x >= 1 && y >= 4) { --x; y -= 4; alice = !alice; }
        return alice ? "Bob" : "Alice";
    }
};

